import{_ as a,o as n,c as s,ag as t}from"./chunks/framework.DC2anBTf.js";const h=JSON.parse('{"title":"Auth & Guards","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/auth.md","filePath":"en/guide/auth.md","lastUpdated":1793538094000}'),i={name:"en/guide/auth.md"};function o(r,e,l,c,d,p){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="auth-guards" tabindex="-1">Auth &amp; Guards <a class="header-anchor" href="#auth-guards" aria-label="Permalink to &quot;Auth &amp; Guards&quot;">​</a></h1><h2 id="the-design-challenge" tabindex="-1">The Design Challenge <a class="header-anchor" href="#the-design-challenge" aria-label="Permalink to &quot;The Design Challenge&quot;">​</a></h2><p>The Web-era experience is reading the token synchronously with <code>js-cookie</code> and grabbing it anywhere. But uni-app x persistence (ux-storage) is <strong>asynchronous</strong>, while guards and request interceptors are &quot;synchronous-minded&quot; — letting async/await infect them pollutes the entire call chain.</p><p>The solution is an <strong>in-memory cache + an explicit readiness primitive</strong> (<code>utils/auth.uts</code>):</p><ul><li>Writes take effect in memory immediately and persist asynchronously; reads are always synchronous;</li><li><code>ensureAuthReady()</code>: awaited on the first line of the guard chain at cold start, restoring the in-memory cache from the persistence layer. The internal Promise is reused — the persistence layer is read exactly once, concurrent calls share the same Promise, no races.</li></ul><p>Asynchrony is compressed into the single moment of startup; the rest of the chain (guards, interceptors, pages) returns to a synchronous mindset.</p><h2 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span>Login → setToken (immediate in memory + async persistence via ux-storage)</span></span>
<span class="line"><span>      → request interceptor injects Authorization: Bearer</span></span>
<span class="line"><span>Cold start → ensureAuthReady() restores the memory cache first → guard chain works normally</span></span></code></pre></div><h2 id="guard-chain-router-permission-uts" tabindex="-1">Guard Chain (router/permission.uts) <a class="header-anchor" href="#guard-chain-router-permission-uts" aria-label="Permalink to &quot;Guard Chain (router/permission.uts)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span>await ensureAuthReady()</span></span>
<span class="line"><span>├─ Has token</span></span>
<span class="line"><span>│   ├─ Visiting login page → redirect home</span></span>
<span class="line"><span>│   ├─ User info present → allow</span></span>
<span class="line"><span>│   └─ No user info → await getInfoAction</span></span>
<span class="line"><span>│       ├─ Success → allow</span></span>
<span class="line"><span>│       └─ Failure → resetToken + redirect to login (with redirect)</span></span>
<span class="line"><span>└─ No token</span></span>
<span class="line"><span>    ├─ Whitelisted (login page) → allow</span></span>
<span class="line"><span>    └─ Otherwise → redirect to login (query carries redirect=path)</span></span></code></pre></div><p>Whitelist: the <code>whiteList</code> array (currently the login page only). New pages require login by default; pages that skip login must be registered in the whitelist.</p><h2 id="cold-start-re-run" tabindex="-1">Cold-Start Re-Run <a class="header-anchor" href="#cold-start-re-run" aria-label="Permalink to &quot;Cold-Start Re-Run&quot;">​</a></h2><p>On cold start (H5 direct entry / deeplink), the page may have loaded without the guard running. <code>setupPermission()</code> explicitly calls <code>router.guardRoute(null, null)</code> after <code>router.isReady()</code> to re-run the guard chain, with the redirect executed as a relaunch.</p><h2 id="navigation-fallback" tabindex="-1">Navigation Fallback <a class="header-anchor" href="#navigation-fallback" aria-label="Permalink to &quot;Navigation Fallback&quot;">​</a></h2><p>The runtime enables <code>InterceptorPlugin</code> (<code>interceptUniApi: true</code>): raw native navigation such as direct <code>uni.navigateTo</code> calls is intercepted and handed to the guard chain. This is defense in depth — the convention still requires going through <code>useRouter()</code> and never relying on the fallback.</p><h2 id="separation-of-concerns" tabindex="-1">Separation of Concerns <a class="header-anchor" href="#separation-of-concerns" aria-label="Permalink to &quot;Separation of Concerns&quot;">​</a></h2><ul><li><strong>Token read/write</strong>: <code>utils/auth.uts</code> (mirrors js-cookie&#39;s responsibility);</li><li><strong>Login/logout actions</strong>: <code>stores/modules/user.uts</code> (loginAction / logoutAction / resetToken);</li><li><strong>Logging out</strong>: <code>showModalAsync</code> confirmation dialog (standard semantics for destructive operations) → logoutAction calls the API (failure does not block local cleanup) → clears state and persistence → relaunch to the login page.</li></ul><p>ux-pinia 0.2.0&#39;s built-in persistence plugin is <strong>not used for tokens</strong>: it avoids splitting persistence semantics across ux-storage and the built-in plugin (criteria in the repository task documents). The built-in persistence is left for business-state scenarios such as drafts.</p>`,18)])])}const g=a(i,[["render",o]]);export{h as __pageData,g as default};
